import { describe, it, expect } from 'vitest';
import { imageHeaderDimensions, assertImagePixelBudget } from '../src/lib/imageDimensions';
import { sameStoredAssetMetadata } from '../src/lib/projectStore';
describe('image admission and lightweight saves',()=>{
 it('rejects high-pixel PNGs before any bitmap allocation',()=>{const b=new Uint8Array(24);b.set([137,80,78,71,13,10,26,10]);b.set([73,72,68,82],12);const v=new DataView(b.buffer);v.setUint32(16,50000);v.setUint32(20,50000);expect(imageHeaderDimensions(b)).toEqual({width:50000,height:50000});expect(()=>assertImagePixelBudget(50000,50000)).toThrow(/decode limit/);});
 it('safely leaves unknown/truncated headers to the decoder',()=>{expect(imageHeaderDimensions(new Uint8Array([255,216,255,225,255,255]))).toBeNull();});
 it('recognizes JPEG frame dimensions without decompressing the artwork',()=>{const bytes=new Uint8Array([255,216,255,192,0,8,8,4,56,10,16,0,255,217]);expect(imageHeaderDimensions(bytes)).toEqual({width:2576,height:1080});});
 it('rewrites changed media metadata but reuses unchanged original records',()=>{const a={id:'a',order:0,path:'assets/a',name:'a.png',type:'image/png',size:9,sha256:'a'.repeat(64)};expect(sameStoredAssetMetadata(a,{...a})).toBe(true);for(const changed of [{size:10},{sha256:'b'.repeat(64)},{order:1},{name:'changed'},{path:'assets/b'}])expect(sameStoredAssetMetadata(a,{...a,...changed})).toBe(false);});
});

import { describe, expect, it } from "vitest";
import { mapMediaSettled } from "../src/lib/mediaWork";
import { mediaSha256 } from "../src/lib/mediaDigest";
import { formatFrameTime } from "../src/components/TimelineDock";

describe("bounded media work", () => {
  it("caps concurrent work, preserves order, and isolates a bad source", async () => {
    let active = 0; let maximum = 0;
    const result = await mapMediaSettled([0,1,2,3,4], async (i) => {
      maximum = Math.max(maximum, ++active);
      await new Promise((resolve) => setTimeout(resolve, 2));
      active--; if (i === 2) throw new Error("corrupt"); return i;
    }, 2);
    expect(maximum).toBe(2);
    expect(result.map((v) => v.status === "fulfilled" ? v.value : "bad")).toEqual([0,1,"bad",3,4]);
  });
  it("hashes an immutable blob only once, not all originals for each slider change", async () => {
    const blob = new Blob(["original"]);
    expect(mediaSha256(blob)).toBe(mediaSha256(blob));
    expect(await mediaSha256(blob)).toHaveLength(64);
    expect(await mediaSha256(new Blob(["changed"]))).not.toBe(await mediaSha256(blob));
  });
  it.each([24,25,30,50,60])("gives adjacent output frames distinct clocks at %i fps", (fps) => {
    expect(formatFrameTime(1 / fps, fps)).not.toBe(formatFrameTime(2 / fps, fps));
    expect(formatFrameTime(60, fps)).toBe("1:00:00");
  });
});

import { describe, expect, it } from "vitest";
import { DEFAULT_SLIDE_VIDEO, slideVideoTime, videoSlideBudget } from "../src/core/media/videoPlayback";
import { createDefaultDriftProjectV4 } from "../src/core/project/defaults";
import { validateDriftProjectV4 } from "../src/core/project/validation";
import { evaluateProjectFrame } from "../src/core/render/projectFrameAdapter";
import type { StudioAsset } from "../src/model";

function fixture() {
  const p = createDefaultDriftProjectV4("video-test", "2026-09-05T00:00:00.000Z");
  const blob = new Blob(["original"], { type: "video/mp4" });
  const a: StudioAsset = { id: "clip", name: "clip.mp4", kind: "video", mimeType: blob.type, blob, hash: "a".repeat(64), objectUrl: "blob:clip", width: 320, height: 180, duration: 2 };
  p.media.order = [a.id];
  p.media.assets[a.id] = { id: a.id, name: a.name, kind: a.kind, mimeType: a.mimeType, hash: a.hash!, byteLength: blob.size, width: a.width, height: a.height, duration: a.duration };
  p.slides[a.id] = { assetId: a.id, fit: "cover", focalX: .5, focalY: .5, scaleOffset: 0, video: { ...DEFAULT_SLIDE_VIDEO } };
  return { p, a };
}

describe("video slides", () => {
  it("loops the source on the authored clock, including repeated cards", () => {
    expect(slideVideoTime(0, 2)).toBe(0);
    expect(slideVideoTime(2, 2)).toBe(0);
    expect(slideVideoTime(5.5, 2)).toBe(1.5);
    expect(slideVideoTime(3, 5, { loop: true, trimStart: 1, trimEnd: 3, rate: 1 })).toBe(2);
  });
  it("holds the final decodable frame when looping is off", () => {
    const t = slideVideoTime(12, 2, { ...DEFAULT_SLIDE_VIDEO, loop: false });
    expect(t).toBeLessThan(2); expect(t).toBeGreaterThan(1.99);
  });
  it("preserves video directives and original identity through V4 validation and rendering", () => {
    const { p, a } = fixture();
    const reopened = validateDriftProjectV4(JSON.parse(JSON.stringify(p)));
    expect(reopened.slides.clip!.video).toEqual(DEFAULT_SLIDE_VIDEO);
    const frame = evaluateProjectFrame({ project: reopened, assets: [a], time: 1, frameIndex: null });
    expect(frame.sourceOrder).toEqual([a.id]);
    expect(frame.renderables.every((item) => item.asset.blob === a.blob)).toBe(true);
  });
  it("rejects invalid trims instead of silently changing them", () => {
    const { p } = fixture(); p.slides.clip!.video!.trimStart = 3;
    expect(() => validateDriftProjectV4(p)).toThrow("invalid trim");
  });
  it("bounds simultaneous clip workload, not ordinary image counts", () => {
    const clip = { kind: "video", width: 1920, height: 1080 };
    expect(videoSlideBudget(Array(8).fill(clip))).toBeNull();
    expect(videoSlideBudget(Array(9).fill(clip))).toContain("8 video slides");
    expect(videoSlideBudget(Array(200).fill({ ...clip, kind: "image" }))).toBeNull();
  });
});
